const body = $json.body ?? $json;
const sizesPedidos = (body.sizes && body.sizes.length) ? body.sizes : ['1:1'];
// Nano Banana (gemini-2.5-flash-image) nao tem campo dedicado de aspect ratio documentado de
// forma confiavel - orientacao de proporcao entra como texto no proprio prompt (abordagem
// pratica conhecida pra esse modelo).
const mapaProporcao = {
  '1:1': 'formato quadrado 1:1',
  '9:16': 'formato vertical 9:16, bem mais alto que largo'
};

return sizesPedidos.map((prop) => {
  const instrucaoProporcao = mapaProporcao[prop] || mapaProporcao['1:1'];
  return {
    json: {
      prompt: body.prompt + ' A imagem deve estar em ' + instrucaoProporcao + '. Sem nenhum texto, letra, palavra ou marca d\'agua na imagem.',
      proporcao: prop,
      file_prefix: body.file_prefix || 'imagem-gerada',
      bloco: body.bloco || null,
      peca: body.peca || null
    }
  };
});

const items = $input.all();
const pedidos = $('Preparar Tamanhos').all();

const imagens = items.map((item, idx) => {
  const meta = pedidos[idx].json;
  const candidates = item.json.candidates || [];
  let b64 = null;
  let mimeType = null;
  for (const c of candidates) {
    const parts = (c.content && c.content.parts) || [];
    for (const p of parts) {
      if (p.inlineData && p.inlineData.data) {
        b64 = p.inlineData.data;
        mimeType = p.inlineData.mimeType || 'image/png';
        break;
      }
    }
    if (b64) break;
  }
  return {
    filename: meta.file_prefix + '_' + meta.proporcao.replace(':', 'x') + '.png',
    proporcao: meta.proporcao,
    mimeType: mimeType,
    base64: b64,
    sucesso: !!b64
  };
});

return [{
  json: {
    bloco: pedidos[0] ? pedidos[0].json.bloco : null,
    peca: pedidos[0] ? pedidos[0].json.peca : null,
    provedor: 'gemini-2.5-flash-image',
    gerado_em: new Date().toISOString(),
    imagens: imagens
  }
}];
